<?php
header('location:alumni-join.php');
exit();
session_start();
require_once('dbstring.php');
require_once('alumni-utils.php');
alumni_ensure_tables($con);
if(empty($_SESSION['alumni_register_csrf'])){ $_SESSION['alumni_register_csrf']=bin2hex(random_bytes(24)); }
$message=''; $messageType='';
if(isset($_POST['register_alumnus'])){
    $name=trim((string)($_POST['fullname']??''));$year=(int)($_POST['graduationyear']??0);$mobile=trim((string)($_POST['mobile']??''));$email=trim((string)($_POST['email']??''));
    if(!hash_equals($_SESSION['alumni_register_csrf'],(string)($_POST['csrf']??'')) || trim((string)($_POST['website']??''))!==''){$message='We could not verify the form. Please refresh and try again.';$messageType='error';}
    elseif($name===''||$year<1950||$year>(int)date('Y')+1||($mobile===''&&$email==='')){$message='Please enter your name, completion year, and at least one contact detail.';$messageType='error';}
    else{$id=alumni_new_id('REG');$programme=trim((string)($_POST['programme']??''));$location=trim((string)($_POST['locationtext']??''));$occupation=trim((string)($_POST['occupation']??''));$organisation=trim((string)($_POST['organisation']??''));$contact=trim((string)($_POST['contactpreference']??'Phone'));$status='pending';$recordedBy='Website Alumni Registration';$stmt=mysqli_prepare($con,'INSERT INTO tblalumni(alumniid,fullname,graduationyear,programme,mobile,email,locationtext,occupation,organisation,contactpreference,status,recordedby) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');if($stmt){mysqli_stmt_bind_param($stmt,'ssisssssssss',$id,$name,$year,$programme,$mobile,$email,$location,$occupation,$organisation,$contact,$status,$recordedBy);if(mysqli_stmt_execute($stmt)){$message='Thank you for registering. AYISEC will review your details before adding you to the alumni register.';$messageType='success';$_SESSION['alumni_register_csrf']=bin2hex(random_bytes(24));}else{$message='Your registration could not be saved. Please try again shortly.';$messageType='error';}mysqli_stmt_close($stmt);}}
}
function arv($key){return alumni_safe($_POST[$key]??'');}
