put name="graduationyear" type="number" min="1950" max="<?php echo date('Y')+1;?>" required placeholder="e.g. 2018" value="<?php echo arv('graduationyear');?>"></label><label>Programme / class<input name="programme" placeholder="e.g. Business 2" value="<?php echo arv('programme');?>"></label><label>Phone number <span>(or email)</span><input name="mobile" placeholder="e.g. 024 000 0000" value="<?php echo arv('mobile');?>"></label><label>Email address <span>(or phone)</span><input name="email" type="email" placeholder="you@example.com" value="<?php echo arv('email');?>"></label><label>Current location<input name="locationtext" placeholder="Town / country" value="<?php echo arv('locationtext');?>"></label><label>Occupation / profession<input name="occupation" value="<?php echo arv('occupation');?>"></label><label class="wide">Organisation / workplace <span>(optional)</span><input name="organisation" value="<?php echo arv('organisation');?>"></label><label>Best way to contact you<select name="contactpreference"><option value="Phone">Phone call</option><option value="WhatsApp">WhatsApp</option><option value="Email">Email</option></select></label><div class="consent"><i class="fa fa-shield"></i><span>By submitting, you confirm these details are correct and agree to be contacted by AYISEC about alumni matters.</span></div><button name="register_alumnus">Submit my registration <i class="fa fa-arrow-right"></i></button></div></form></div></section></main><footer><span>© <?php echo date('Y');?> Ayirebi Senior High School</span><a href="website.php">Return to school website</a></footer><?php include('alumni-help-widget.php'); ?></body></html>
